"""Read COBOL field metadata from GnuCOBOL generated files."""
from pathlib import Path
import re

def fields_from_c(path):
    path = Path(path)
    texts = []
    seen = set()
    def visit(file):
        file = file.resolve()
        if file in seen:
            return
        seen.add(file)
        try:
            text = file.read_text(encoding='utf-8', errors='replace')
        except OSError:
            return
        if not re.search(r'/\* Generated by\s+cobc\b', text):
            return
        texts.append(text)
        for include in re.findall(r'^\s*#include "([^"\n]+)"', text, re.M):
            visit(file.parent / include)
    visit(path)
    text = '\n'.join(texts)
    attrs = {key: (int(kind, 0), int(scale), int(flags, 0))
        for key, kind, scale, flags in re.findall(
            r'cob_field_attr\s+(a_\d+)\s*=\s*\{(0x[\da-fA-F]+),\s*\d+,\s*(-?\d+),\s*(0x[\da-fA-F]+)', text)}
    result = []
    for symbol, size, attr, name in re.findall(
            r'cob_field\s+(f_\d+)\s*=\s*\{(\d+),[^;]+?&(a_\d+)\s*\};\s*/\*\s*(.*?)\s*\*/', text):
        if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9-]*', name) or name.upper() == 'FILLER':
            continue
        result.append({'name': name, 'symbol': symbol, 'size': int(size),
                       'attribute': attrs.get(attr)})
    return result

def display_value(raw, attribute):
    if attribute:
        kind, scale, flags = attribute
        if kind == 0x10 and flags == 0 and raw.isdigit():
            text = raw.decode('ascii')
            if scale > 0:
                text = text.zfill(scale+1)
                text = text[:-scale] + '.' + text[-scale:]
            elif scale < 0:
                text += '0' * -scale
            return text, 'numeric DISPLAY'
        if kind in (0x01, 0x21):
            text = raw.decode('latin-1').rstrip(' ')
            return ''.join(c if c.isprintable() else f'\\x{ord(c):02x}' for c in text), 'group/text'
    return raw.hex(' '), 'raw bytes (format not decoded)'
